INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein IT-Betrieb verpflichtet, Maßnahmen zur Energieeffizienz umzusetzen?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche und nachhaltige Anforderungen"}, {"text": "Nein", "correct": false, "because": "Energieeffizienz ist oft vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Einsatz energieeffizienter Hardware die Betriebskosten senken?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Energieverbrauch reduziert Kosten"}, {"text": "Nein", "correct": false, "because": "Kostensenkung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Maßnahmen zur Energieeffizienz immer mit hohen Investitionen verbunden sein?', 2, '[{"text": "Ja", "correct": false, "because": "Kleine Maßnahmen können auch effektiv sein"}, {"text": "Nein", "correct": true, "because": "Kostengünstige Lösungen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Energieeffizienz sein Image verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}, {"text": "Nein", "correct": false, "because": "Imagevorteil ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Überwachung des Energieverbrauchs ein Teil der Energieeffizienz?', 2, '[{"text": "Ja", "correct": true, "because": "Kontrolle ist essenziell"}, {"text": "Nein", "correct": false, "because": "Überwachung gehört dazu"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Energieeffizienz in Unternehmen?', 2, '[{"text": "Energiewirtschaftsgesetz (EnWG)", "correct": true, "because": "Regelt Energieeffizienzpflichten"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Energieeffizienz im IT-Betrieb?', 3, '[{"text": "Reduzierung des Energieverbrauchs", "correct": true, "because": "Kernziel der Energieeffizienz"}, {"text": "Erhöhung der Produktionskosten", "correct": false, "because": "Kein Ziel"}, {"text": "Vermeidung von Hardware", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme fördert die Energieeffizienz in einem IT-Betrieb?', 2, '[{"text": "Einsatz energieeffizienter Server", "correct": true, "because": "Reduziert Verbrauch"}, {"text": "Verwendung veralteter Geräte", "correct": false, "because": "Ineffizient"}, {"text": "Ausschalten der Klimaanlage", "correct": false, "because": "Nicht immer praktikabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz kann mangelnde Energieeffizienz haben?', 3, '[{"text": "Höhere Betriebskosten", "correct": true, "because": "Mehr Energieverbrauch"}, {"text": "Geringere Arbeitszeit", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Bessere Produktivität", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist im IT-Betrieb für die Umsetzung von Energieeffizienz verantwortlich?', 2, '[{"text": "Das Management", "correct": true, "because": "Verantwortlich für Maßnahmen"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nicht deren Aufgabe"}, {"text": "Die Kunden", "correct": false, "because": "Keine Rolle"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Energieeffizienz im IT-Betrieb?', 4, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Verbrauch"}, {"text": "Optimierung der Kühlung", "correct": true, "because": "Senkt Energiekosten"}, {"text": "Nutzung veralteter Technik", "correct": false, "because": "Ineffizient"}, {"text": "Energieüberwachung", "correct": true, "because": "Ermöglicht Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Energieeffizienz im IT-Betrieb?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Weniger Energieverbrauch"}, {"text": "Verbessertes Image", "correct": true, "because": "Nachhaltigkeit positiv"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Umweltschutz", "correct": true, "because": "Weniger Emissionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln die Energieeffizienz?', 4, '[{"text": "Energiewirtschaftsgesetz (EnWG)", "correct": true, "because": "Regelt Energieeffizienz"}, {"text": "Energieeffizienzrichtlinie (EU)", "correct": true, "because": "EU-Vorgaben"}, {"text": "Kündigungsschutzgesetz (KSchG)", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Erneuerbare-Energien-Gesetz (EEG)", "correct": true, "because": "Fördert Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat mangelnde Energieeffizienz im IT-Betrieb?', 3, '[{"text": "Höhere Energiekosten", "correct": true, "because": "Mehr Verbrauch"}, {"text": "Schlechtes Image", "correct": true, "because": "Fehlende Nachhaltigkeit"}, {"text": "Geringere Hardwarekosten", "correct": false, "because": "Kein Effekt"}, {"text": "Umweltbelastung", "correct": true, "because": "Höhere Emissionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche können in einem IT-Betrieb energieeffizient gestaltet werden?', 3, '[{"text": "Serverräume", "correct": true, "because": "Hoher Energieverbrauch"}, {"text": "Beleuchtung", "correct": true, "because": "Optimierung möglich"}, {"text": "Produktverpackung", "correct": false, "because": "Kein direkter Bezug"}, {"text": "Arbeitsplätze", "correct": true, "because": "Effiziente Geräte nutzbar"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Energieeffizienz senkt die Betriebskosten. b) Sie erfordert immer hohe Investitionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (kleine Maßnahmen möglich)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Energieeffiziente Server reduzieren den Verbrauch. b) Überwachung ist irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Überwachung wichtig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Energieeffizienz schützt die Umwelt. b) Sie hat keinen Einfluss auf das Image.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Imagevorteil)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das EnWG regelt Energieeffizienz. b) Nur Auszubildende sind dafür verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Management zuständig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mangelnde Energieeffizienz erhöht Kosten. b) Sie fördert die Nachhaltigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Kosten steigen, b) Nachhaltigkeit gefördert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
